1	#!/usr/bin/env bun
2	/**
3	 * manage_in_progress_label.ts — Add or remove the config.yaml-configured
4	 * "in_progress" label on an issue/PR (works for PR numbers too, since
5	 * GitHub treats every PR as an issue under the hood). Best-effort: never
6	 * fails the calling step, only logs a warning (matching the previous
7	 * `2>/dev/null || true` bash behavior).
8	 *
9	 * Usage: manage_in_progress_label.ts --action add|remove --number N
10	 */
11	import { parseArgs } from "node:util";
12	import { gh } from "../../adapters/github/gh.ts";
13	import { getLabel } from "../../adapters/runner/config.ts";
14	import { defineScript } from "./lib/script-ref.ts";
15	
16	export interface ManageInProgressLabelArgs {
17	  action: "add" | "remove";
18	  number: string | number;
19	}
20	
21	export const ref = defineScript<ManageInProgressLabelArgs>(import.meta.url);
22	
23	function main(): void {
24	  const { values } = parseArgs({
25	    args: Bun.argv.slice(2),
26	    options: {
27	      action: { type: "string" },
28	      number: { type: "string" },
29	    },
30	  });
31	
32	  if (values.action !== "add" && values.action !== "remove") {
33	    console.error("usage: manage_in_progress_label.ts --action add|remove --number N");
34	    process.exit(2);
35	  }
36	  if (!values.number) {
37	    console.error("usage: manage_in_progress_label.ts --action add|remove --number N");
38	    process.exit(2);
39	  }
40	
41	  const label = getLabel("in_progress");
42	
43	  if (values.action === "add") {
44	    // Create the label if it does not exist yet.
45	    gh("label", "create", label, "--force", "-c", "0366d6", "-d", "Issue is being worked on by an Atomaton agent");
46	    const { code } = gh("issue", "edit", values.number, "--add-label", label);
47	    if (code !== 0) console.error(`Warning: failed to add '${label}' label to #${values.number}`);
48	  } else {
49	    const { code } = gh("issue", "edit", values.number, "--remove-label", label);
50	    if (code !== 0) console.error(`Warning: failed to remove '${label}' label from #${values.number}`);
51	  }
52	}
53	
54	if (import.meta.main) main();

